import torch
import torch.nn as nn

class ModelNew(nn.Module):
    """
    Performs a 3D transposed convolution operation with asymmetric input and square kernel.
    The input is padded before the convolution.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel.
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Custom CUDA operator for transposed convolution
        self.transposed_conv = torch.nn.functional.TransposeConvolution2d(
            in_channels,
            out_channels,
            kernel_size=kernel_size,
            stride=stride,
            padding=padding,
            groups=groups,
            bias=bias,
            device="cuda",
            dtype=torch.float32
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 3D transposed convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out).
        """
        return self.transposed_conv(x)

# Define the custom CUDA kernel for transposed convolution
transposed_conv_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_conv2d_kernel(
    float* input,
    float* output,
    int rows, int cols,
    int stride,
    int padding,
    int groups,
    int kernel_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * cols * kernel_size * stride * padding) {
        // Calculate the corresponding input and output indices
        int row_offset = idx % (kernel_size * stride * padding);
        int col_offset = (idx / (kernel_size * stride * padding)) % (cols - 1);

        // Apply transposed convolution logic
        float sum = 0.0;
        for (int i = 0; i < kernel_size; i++) {
            for (int j = 0; j < kernel_size; j++) {
                int row = row_offset + i * stride + padding;
                int col = col_offset + j * stride + padding;
                if (row >= rows && col >= cols) continue;
                sum += input[row * cols * kernel_size * stride + col] * output[row * cols * kernel_size * stride + col];
            }
        }
        output[idx] = sum / (kernel_size * stride * padding);
    }
}

# Compile the inline CUDA code for transposed convolution
transposed_conv_cpp_source = (
    "torch::Tensor transposed_conv2d_kernel(torch::Tensor input, torch::Tensor output, int rows, int cols, int stride, int padding, int groups, int kernel_size);"
)

# Load the custom CUDA code
transposed_conv = load_inline(
    name="transposed_conv",
    cpp_sources=transposed_conv_cpp_source,
    cuda_sources=transposed_conv_kernel,
    functions=["transposed_conv2d_kernel"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# Create the ModelNew class
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Initialize the transposed convolution layer
        self.transposed_conv = transposed_conv

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 3D transposed convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out).
        """
        return self.transposed_conv(x)

